#!/usr/bin/env python3
"""Configure a fresh copy of the template; Python is not a project dependency."""
import argparse
from datetime import date
import hashlib
import json
import os
from pathlib import Path
import re
import subprocess
import sys
import tempfile

ROOT = Path(__file__).resolve().parent
# Generated by the template maintainer; changed files require an explicit refresh.
EXPECTED = {'Cargo.toml': '6d084b74b93af97c6a32606547436a9f5bb2772bb5f2351da089c7ea5cad6475', 'Cargo.lock': 'bfbd60ba543d9c2c1ceeeac39588bc90de2c16f75df0a5bc557376110e369689', 'src/lib.rs': '0b1b24979f994d48b846d8eb3cc9d9481c6bcf86ffb1d63ddcfed0eb8c903a9e', 'src/main.rs': '26c3a0a9eb6674548456fafa024de47f6f204ebc285544fd03a2a84ce460d515', 'tests/cli.rs': '06e7bfdc1779558c175bc4542d6cdfa322f4421c88fa1babca965165adf8ebfa', 'README.md': '37619f364e9783a52057a446b579635d3a5c0569b97c91f2b277d452410b13dd', 'installation.md': '7a2e20638503ee0bbd5c2ea5e59beecf302584d3d1938670d70bd33d31228bf6', 'LICENSE': 'eba5442e0d6da4bf2716a0f0bfbc7b3454bf266d7e6db4ef7e55f9f4c7b4a6cb', 'Makefile': 'a75b0fe19b28f101282491618bca6862c7cd25c4e5889a9e99d0312d080ff5fd', 'development.md': '8ccd6cdfa040e84d7d4150348d1637df1009e6b6f90f9ccf2adce2f8e2336044', 'scripts/refresh_bootstrap_hashes.py': 'd57678f2a13e762c8ff9a87bec266d50a08c1db495110b8e76ae94695ac2c111', 'scripts/template_test.py': 'd4ad8331b2f3cc431aa8c01611b2200fdc51e1ca5f23d60ecc76623635ebb225', '.github/workflows/template.yml': 'bb5959f86a2af5458c170803cd8d80af1e26b2c9f4b84bc97780864e5beca3ec'}  # BOOTSTRAP_HASHES
RESERVED = set('as break const continue crate else enum extern false fn for if impl in let loop match mod move mut pub ref return self Self static struct super trait true type unsafe use where while async await dyn abstract become box do final macro override priv typeof unsized virtual yield try gen'.split())


# Names that conflict with Rust's standard crates, our direct dependency, or
# Windows device filenames cannot produce a portable project.
RESERVED_NAMES = {'std', 'core', 'alloc', 'proc_macro', 'clap', 'con', 'prn', 'aux', 'nul'} | {f'{prefix}{number}' for prefix in ('com', 'lpt') for number in range(1, 10)}


def template_hash(path):
    # Git may check text files out with CRLF on Windows; compare their content.
    return hashlib.sha256(path.read_bytes().replace(b'\r\n', b'\n')).hexdigest()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    for option in ('name', 'owner', 'author', 'email', 'description'):
        parser.add_argument('--' + option)
    args = parser.parse_args()
    for key in ('name', 'owner', 'author', 'email', 'description'):
        if getattr(args, key) is None:
            if not sys.stdin.isatty():
                parser.error(f'--{key} is required in non-interactive mode')
            setattr(args, key, input(f'{key.capitalize()}: ').strip())
    if (len(args.name) > 64 or not re.fullmatch(r'[a-z][a-z0-9]*(?:-[a-z0-9]+)*', args.name)
            or args.name.replace('-', '_') in RESERVED | RESERVED_NAMES):
        parser.error('name must be at most 64 characters, use lowercase ASCII letters, digits and single hyphens, start with a letter, and avoid reserved or conflicting names')
    if not re.fullmatch(r'[A-Za-z0-9](?:[A-Za-z0-9-]{0,37}[A-Za-z0-9])?', args.owner):
        parser.error('owner must be a GitHub account or organization name')
    if any(not getattr(args, k).strip() or any(ord(c) < 32 for c in getattr(args, k)) for k in ('author', 'email', 'description')) or not re.fullmatch(r'[^\s<>@]+@[^\s<>@]+', args.email):
        parser.error('author, email, and description must be nonempty single-line values; email must be valid')
    for path, digest in EXPECTED.items():
        file = ROOT / path
        if not file.is_file() or template_hash(file) != digest:
            raise ValueError(f'{path} is missing or changed; restore the template before bootstrap')
    replacements = {
        'Cargo.toml': [(json.dumps('simple-modern-rust'), json.dumps(args.name)), (json.dumps('Template Author <author@example.com>'), json.dumps(f'{args.author} <{args.email}>', ensure_ascii=False)), (json.dumps('A small Rust command-line application'), json.dumps(args.description, ensure_ascii=False)), ('https://github.com/template-owner/simple-modern-rust', f'https://github.com/{args.owner}/{args.name}')],
        'Cargo.lock': [('name = "simple-modern-rust"', f'name = "{args.name}"')],
        'src/lib.rs': [('simple_modern_rust', args.name.replace('-', '_'))],
        'src/main.rs': [('simple_modern_rust', args.name.replace('-', '_'))],
        'tests/cli.rs': [('simple-modern-rust', args.name)],
        'README.md': [('simple-modern-rust', args.name), ('A small Rust command-line application.', args.description), ('\n## Create a project from this template\n', '\n## Create a project from this template\n')],
        'installation.md': [('simple-modern-rust', args.name)],
        'LICENSE': [('Copyright (c) 2026 Template Author', f'Copyright (c) {date.today().year} {args.author}')],
        'Makefile': [('template-test:\n\tpython3 scripts/template_test.py\n\n', '')],
        'development.md': [(' The template maintainer can use `make template-test` to exercise bootstrap.', '')],
    }
    deletions = ['bootstrap.py', 'scripts/template_test.py', 'scripts/refresh_bootstrap_hashes.py', '.github/workflows/template.yml']
    with tempfile.TemporaryDirectory(prefix='rust-bootstrap-') as temp:
        stage = Path(temp)
        files = {}
        for path, pairs in replacements.items():
            content = (ROOT / path).read_text(encoding='utf-8')
            for old, new in pairs:
                if old not in content:
                    raise ValueError(f'missing expected marker in {path}: {old}')
                content = content.replace(old, new)
            if path == 'README.md':
                content = content.split('\n## Create a project from this template\n')[0] + '\n'
            files[path] = content.encode('utf-8')
        # Validate Cargo metadata before touching the checkout.
        for path in ('Cargo.toml', 'Cargo.lock'):
            (stage / path).write_bytes(files[path])
        (stage / 'src').mkdir()
        (stage / 'src/main.rs').write_text('fn main() {}\n')
        subprocess.run(['cargo', 'metadata', '--locked', '--offline', '--no-deps', '--format-version', '1'], cwd=stage, stdout=subprocess.DEVNULL, check=True)
        originals = {path: (ROOT / path).read_bytes() for path in [*files, *deletions]}
        for path in files:
            tmp = (ROOT / path).with_name((ROOT / path).name + '.bootstrap-tmp')
            if tmp.exists():
                raise ValueError(f'temporary file already exists: {tmp}')
        created = []
        try:
            for path, content in files.items():
                target = ROOT / path
                tmp = target.with_name(target.name + '.bootstrap-tmp')
                created.append(tmp)
                tmp.write_bytes(content)
                os.replace(tmp, target)
            for path in deletions:
                (ROOT / path).unlink()
        except Exception:
            for path, content in originals.items():
                (ROOT / path).write_bytes(content)
            for tmp in created:
                tmp.unlink(missing_ok=True)
            raise
    print('Project configured. Review changes, check crate-name availability, update documentation, and enable CI or publishing when ready.')


if __name__ == '__main__':
    try:
        main()
    except (ValueError, OSError, subprocess.CalledProcessError) as exc:
        print(f'bootstrap: {exc}', file=sys.stderr)
        sys.exit(1)
